  $sections$[{"type":"header","variant":"clasico"},{"type":"hero","variant":"cuenta-regresiva","titulo":"Valentina","fechaEvento":"2026-11-14T21:00:00-03:00","fechaEventoLabel":"Sábado 14 de noviembre · 2026","botones":{"primary":{"funcion":"seccion","label":"Confirmar mi asistencia"}}},{"type":"sobre-nosotros","variant":"split","titulo":"La invitación","quote":"Hay momentos que se sueñan durante años. Este es uno, y quiero vivirlo con la gente que quiero.","firma":"Valen","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/9dd4ce42-ca33-4a7b-a12a-dfab1395f827.jpg"},{"type":"cronograma","eyebrow":"Cronograma","titulo":"Cómo va a ser la noche","descripcion":"Te dejamos los horarios para que no te pierdas nada.","items":[{"id":"cron-1","time":"20:30","title":"Recepción","desc":"Te esperamos con la barra abierta y algo para picar mientras llegan todos."},{"id":"cron-2","time":"21:15","title":"Entrada de Valentina","desc":"El momento más esperado de la noche. Por favor, guardá los celulares un minuto."},{"id":"cron-3","time":"21:40","title":"Vals y brindis","desc":"El vals con familia y padrinos, y después el brindis con todos."},{"id":"cron-4","time":"22:15","title":"Cena","desc":"Servicio en mesa con el menú que elegiste al confirmar."},{"id":"cron-5","time":"23:45","title":"Se abre la pista","desc":"DJ en vivo, carioca y todo lo que haga falta para no parar."},{"id":"cron-6","time":"03:00","title":"Mesa dulce y cierre","desc":"Torta, mesa dulce y la última tanda antes de despedirnos."}]},{"type":"lugares","eyebrow":"Dónde","titulo":"Los dos momentos","items":[{"id":"lugar-1","kind":"Misa","nombre":"Parroquia Santa Lucía","direccion":"Av. Rivadavia 4680, CABA","hora":"19:00 hs","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/4a8bb7c2-01e6-4310-96a6-f25506fa98db.jpg"},{"id":"lugar-2","kind":"Salón","nombre":"Salón Bella Época","direccion":"Bulnes 1290, CABA · Estacionamiento propio","hora":"20:30 hs","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/268fbbc5-6743-4252-9e6b-14a4a909fcd8.jpg"}]},{"type":"dresscode","bgColor":"#33202c","textColor":"#fbf7f4","eyebrow":"Dress code","titulo":"Elegante, pero cómodo para bailar","descripcion":"La idea es que estés lindo y cómodo. Vestido largo o midi, o traje sin corbata. Lo único que te pedimos: dejá el blanco y el rosa viejo para mí.","notas":[{"id":"nota-1","positivo":true,"texto":"Vestido largo o midi, o traje sin corbata."},{"id":"nota-2","positivo":true,"texto":"Traé un calzado cómodo de repuesto para la pista."},{"id":"nota-3","positivo":false,"texto":"Evitá el blanco, el rosa empolvado y el jean."}],"paletaColores":[{"id":"color-1","nombre":"Vino","hex":"#6d2436"},{"id":"color-2","nombre":"Verde salvia","hex":"#8a9a80"},{"id":"color-3","nombre":"Azul noche","hex":"#2c3a58"},{"id":"color-4","nombre":"Camel","hex":"#b58a5f"},{"id":"color-5","nombre":"Negro","hex":"#1c1418"}]},{"type":"rsvp","eyebrow":"Confirmación","titulo":"¿Vas a venir?","descripcion":"Confirmame antes del 31 de octubre así reservamos tu lugar en la mesa.","menuOptions":[{"id":"menu-clasico","nombre":"Menú clásico","desc":"Bife de chorizo con papas rústicas."},{"id":"menu-veggie","nombre":"Menú vegetariano","desc":"Risotto de hongos y calabaza asada."},{"id":"menu-sintacc","nombre":"Menú sin TACC","desc":"Pollo grillado con vegetales y quinoa."}],"mensajeConfirmado":"{nombre} está confirmado para {invitados}, con {menu}. Te vamos a escribir unos días antes con los últimos detalles.","mensajeDeclinado":"Nos vas a hacer falta, pero gracias por tomarte el momento de avisarnos. ¡Nos vemos pronto!"},{"type":"playlist","eyebrow":"Playlist","titulo":"Pedí tu canción","descripcion":"Sumá el tema que no puede faltar y el DJ lo va a tener en la lista.","canciones":[{"id":"song-1","titulo":"Bad Bunny — Tití Me Preguntó","por":"Sofi"},{"id":"song-2","titulo":"Duki — Goteo","por":"Tomás"},{"id":"song-3","titulo":"ABBA — Dancing Queen","por":"Tía Marta"},{"id":"song-4","titulo":"Tan Biónica — La Melodía de Dios","por":"Papá"},{"id":"song-5","titulo":"Rosalía — Despechá","por":"Juli"}]},{"type":"regalos","eyebrow":"Mesa de regalos","titulo":"Tu presencia es el regalo","descripcion":"Pero si querés hacerme un mimo, acá te dejo algunas opciones.","items":[{"id":"regalo-1","glyph":"♡","titulo":"Un sobre","desc":"Si preferís lo clásico, va a haber una urna en la entrada del salón.","detalle":"Urna en recepción"},{"id":"regalo-2","glyph":"⌘","titulo":"Transferencia","desc":"Podés hacerme una transferencia si te queda más cómodo.","detalle":"Alias: valen.xv.2026"},{"id":"regalo-3","glyph":"✈","titulo":"Mi viaje de egresados","desc":"Estoy juntando para el viaje, cualquier ayuda me acerca un poco más.","detalle":"Colecta: valen15viaje"}]},{"type":"galeria","variant":"scroll","titulo":"Antes de la fiesta"},{"type":"footer","variant":"evento","titulo":"Nos vemos ahí","hashtag":"#ValenXV","botones":{"confirmar":{"funcion":"seccion","label":"Confirmar asistencia"},"llegar":{"funcion":"seccion","label":"Cómo llegar"}}}]$sections$::jsonb,
